type Session={userId:string;tenantId:string;email:string;name:string;role:string;permissions:string[]}
const tenantStatus=z.enum(['active','suspended','archived'])
const tenantLifecycleStatus=z.enum(['active','suspended','archived','expired'])
const tenantDate=z.string().trim().refine(v=>!Number.isNaN(Date.parse(v)),{message:'日期时间格式不合法'})
const userPassword=z.string().min(8,'密码至少 8 位').max(128,'密码最多 128 位')
const generateInitialPassword=()=>`Mesh-${randomUUID().replace(/-/g,'').slice(0,12)}!`
const tenantOwnerPermissions=['models:read','models:write','apikeys:manage','members:manage','plans:manage','payments:manage','dictionaries:manage','settings:manage'] as const
const hasPermission=(session:Session,code:string)=>session.permissions.includes('*')||session.permissions.includes(code)
function assertPermission(session:Session,code:string){if(!hasPermission(session,code))throw Object.assign(new Error(`缺少权限 ${code}`),{statusCode:403})}
const toTenantDate=(value?:string|null)=>value?new Date(value):null
const slugifyTenant=(value:string)=>value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||`tenant-${Date.now().toString(36)}`
type TenantAccessRow={status:string;valid_from:Date|string;valid_until:Date|string|null}
type LoginRow=TenantAccessRow&{id:string;email:string;name:string;password_hash:string;tenant_id:string;role:string;permissions:string[]}
function tenantUnavailable(row:TenantAccessRow){const now=Date.now(),from=new Date(row.valid_from).getTime(),until=row.valid_until?new Date(row.valid_until).getTime():null;return row.status!=='active'||from>now||(until!==null&&until<=now)}
async function validateRolePermissions(session:Session,permissions:string[]){const unique=[...new Set(permissions)];if(unique.length!==permissions.length)throw Object.assign(new Error('权限列表包含重复项'),{statusCode:400});if(unique.length){const rows=(await query<{code:string}>(`SELECT code FROM app.permissions WHERE code=ANY($1::varchar[])`,[unique])).rows;if(rows.length!==unique.length)throw Object.assign(new Error('包含未登记的权限代码'),{statusCode:400});if(!session.permissions.includes('*')&&unique.some(code=>!session.permissions.includes(code)))throw Object.assign(new Error('不能授予当前账号不具备的权限'),{statusCode:403})}return unique}
async function bootstrapTenantDefaults(c:pg.PoolClient,tenantId:string){const owner=(await c.query(`INSERT INTO app.roles(tenant_id,name,description,is_system,permissions) VALUES($1,'所有者','租户工作空间全部权限',true,$2) ON CONFLICT(tenant_id,name) DO UPDATE SET permissions=EXCLUDED.permissions RETURNING id`,[tenantId,JSON.stringify(tenantOwnerPermissions)])).rows[0] as {id:string};await c.query(`INSERT INTO app.roles(tenant_id,name,description,is_system,permissions) VALUES($1,'成员','默认只读权限',true,$2) ON CONFLICT(tenant_id,name) DO UPDATE SET permissions=EXCLUDED.permissions`,[tenantId,JSON.stringify(['models:read'])]);const plan=(await c.query(`SELECT id FROM app.plans WHERE code='newer' AND active=true LIMIT 1`)).rows[0] as {id:string}|undefined;if(plan)await c.query(`INSERT INTO app.subscriptions(tenant_id,plan_id,provider,provider_ref,status,period_start,period_end) VALUES($1,$2,'manual','tenant-default','active',now(),now()+interval '1 month') ON CONFLICT DO NOTHING`,[tenantId,plan.id]);const dicts=[['order_status','订单状态',[['待支付','pending','#f59e0b'],['已支付','paid','#10b981'],['已取消','cancelled','#94a3b8'],['已退款','refunded','#ef4444']]],['member_status','成员状态',[['正常','active','#10b981'],['已邀请','invited','#f59e0b'],['已禁用','disabled','#94a3b8']]]] as const;for(const [code,name,items] of dicts){const d=(await c.query(`INSERT INTO app.dictionaries(tenant_id,code,name) VALUES($1,$2,$3) ON CONFLICT(tenant_id,code) DO UPDATE SET name=EXCLUDED.name RETURNING id`,[tenantId,code,name])).rows[0];let sort=0;for(const [label,value,color] of items)await c.query(`INSERT INTO app.dictionary_items(tenant_id,dictionary_id,label,value,color,sort_order) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(dictionary_id,value) DO UPDATE SET label=EXCLUDED.label,color=EXCLUDED.color,sort_order=EXCLUDED.sort_order`,[tenantId,d.id,label,value,color,++sort])}return owner.id}
declare module 'fastify' { interface FastifyRequest { session?: Session; rawBody?: string } }
const app=Fastify({logger:true,bodyLimit:100*1024*1024})
await app.register(cors,{origin:config.appUrl,credentials:true}); await app.register(multipart,{limits:{fileSize:10*1024*1024,files:500,parts:1100}}); await mkdir(config.uploadDir,{recursive:true})
app.addHook('preParsing',async(request,_reply,payload)=>{if(!request.url.startsWith('/api/billing/webhooks/'))return payload;const chunks:Buffer[]=[];const stream=new PassThrough();payload.on('data',chunk=>chunks.push(Buffer.isBuffer(chunk)?chunk:Buffer.from(chunk)));payload.on('end',()=>{request.rawBody=Buffer.concat(chunks).toString('utf8')});payload.on('error',err=>stream.destroy(err));payload.pipe(stream);return stream})
const ok=(data:unknown)=>({data}); const tokenOf=(r:FastifyRequest)=>r.headers.authorization?.replace(/^Bearer\s+/,'')
type ProviderProtocol='openai'|'anthropic'|'ollama'|'custom'
type ProviderRecord={id:string;tenant_id:string;base_url:string;protocol:ProviderProtocol;auth_type:string;encrypted_api_key?:string|null}
function providerHeaders(protocol:ProviderProtocol,authType:string,key?:string){const headers:Record<string,string>={Accept:'application/json'};if(key&&authType==='bearer')headers.Authorization=`Bearer ${key}`;if(key&&(authType==='x-api-key'||protocol==='anthropic')){headers['x-api-key']=key;headers['anthropic-version']='2023-06-01'}return headers}
function providerErrorDetail(raw:string){if(!raw)return '';try{const json=JSON.parse(raw) as {message?:unknown;error?:unknown};if(typeof json.message==='string')return json.message;if(typeof json.error==='string')return json.error;if(json.error&&typeof json.error==='object'&&'message' in json.error&&typeof json.error.message==='string')return json.error.message}catch{}return raw.replace(/\s+/g,' ').trim().slice(0,300)}
async function throwProviderResponseError(response:Response,service:string):Promise<never>{const detail=providerErrorDetail(await response.text());throw new Error(`${service}服务返回 ${response.status}${detail?`：${detail}`:''}`)}
type DiscoveredModel={id:string;name?:string}
function parseDiscoveredModels(protocol:ProviderProtocol,json:unknown):DiscoveredModel[]{const value=json as {data?:unknown;models?:unknown};const list=Array.isArray(json)?json:protocol==='ollama'?value?.models:value?.data??value?.models;if(!Array.isArray(list))return [];return list.flatMap(item=>{if(typeof item==='string')return [{id:item,name:item}];if(!item||typeof item!=='object')return [];const model=item as {id?:unknown;name?:unknown;model?:unknown;display_name?:unknown};const id=typeof model.id==='string'?model.id:typeof model.model==='string'?model.model:typeof model.name==='string'?model.name:'';if(!id)return [];const name=typeof model.display_name==='string'?model.display_name:typeof model.name==='string'?model.name:id;return [{id,name}]})}
async function discoverProviderModels(provider:ProviderRecord,key?:string){const base=provider.base_url.replace(/\/+$/,'');const url=provider.protocol==='ollama'?`${base}/api/tags`:`${base}/models`;let response:Response;try{response=await fetch(url,{headers:providerHeaders(provider.protocol,provider.auth_type,key),signal:AbortSignal.timeout(12000)})}catch(e){throw Object.assign(new Error(`无法连接模型服务：${e instanceof Error?e.message:'网络错误'}；请确认服务地址可从当前服务端访问`),{statusCode:502})}if(!response.ok){const detail=providerErrorDetail(await response.text()),authFailed=response.status===401||response.status===403,statusCode=authFailed?400:response.status===429?429:502;const summary=authFailed?'API Key 无效或无权访问模型列表':response.status===429?'模型服务请求过于频繁或额度不足':`模型服务返回 ${response.status}`;throw Object.assign(new Error(`${summary}${detail?`：${detail}`:''}`),{statusCode})}let json:unknown;try{json=await response.json()}catch{throw Object.assign(new Error('模型服务返回了无法解析的响应，请确认 Base URL 指向兼容 API（通常以 /v1 结尾）'),{statusCode:502})}const models=parseDiscoveredModels(provider.protocol,json);if(!models.length)throw Object.assign(new Error('模型服务未返回可用模型；请确认 Base URL 包含正确的 API 版本路径，或手工填写模型 ID'),{statusCode:502});return models}
async function saveProviderModels(tenantId:string,providerId:string,models:DiscoveredModel[]){const unique=[...new Map(models.map(model=>[model.id.trim(),{id:model.id.trim(),name:(model.name??model.id).trim()}])).values()];const invalid=unique.find(model=>!model.id||model.id.length>150||!model.name||model.name.length>150);if(invalid)throw Object.assign(new Error(`模型列表包含不合法或过长的模型标识：${invalid.id.slice(0,80)}`),{statusCode:502});const existing=(await query<{external_id:string}>(`SELECT external_id FROM app.models WHERE tenant_id=$1 AND provider_id=$2`,[tenantId,providerId])).rows,existingIds=new Set(existing.map(model=>model.external_id)),additional=unique.filter(model=>!existingIds.has(model.id)).length;try{await enforceResourceQuota(tenantId,'models',additional)}catch(e){if((e as {statusCode?:number}).statusCode===429){const entitlements=await currentEntitlements(tenantId),limit=typeof entitlements.models==='number'?entitlements.models:null,used=(await query<{used:number}>(`SELECT count(*)::int used FROM app.models WHERE tenant_id=$1`,[tenantId])).rows[0].used;if(limit!==null)throw Object.assign(new Error(`中转站返回 ${unique.length} 个模型，需新增 ${additional} 个；当前套餐模型额度 ${used}/${limit}，剩余 ${Math.max(0,limit-used)} 个。请减少手工模型 ID 或升级套餐`),{statusCode:429})}throw e}await transaction(async c=>{for(const model of unique)await c.query(`INSERT INTO app.models(tenant_id,provider_id,external_id,name,model_category,context_window) VALUES($1,$2,$3,$4,$5,131072) ON CONFLICT(provider_id,external_id) DO UPDATE SET name=EXCLUDED.name,enabled=true`,[tenantId,providerId,model.id,model.name,inferModelCategory(model.id,model.name)])});return unique.length}
async function auth(r:FastifyRequest,reply:FastifyReply){const token=tokenOf(r);if(!token)return reply.code(401).send({error:'unauthorized',message:'请先登录'});const sessionKey=`session:${sha256(token)}`,raw=await redis.get(sessionKey);if(!raw)return reply.code(401).send({error:'session_expired',message:'登录已过期'});r.session=JSON.parse(raw);const tenant=(await query<TenantAccessRow>(`SELECT status,valid_from,valid_until FROM app.tenants WHERE id=$1`,[r.session!.tenantId])).rows[0];if(!tenant||tenantUnavailable(tenant)){await redis.del(sessionKey);return reply.code(403).send({error:'tenant_unavailable',message:'租户已停用或不在有效期内'})}await redis.expire(sessionKey,86400)}
const permit=(code:string)=>async(r:FastifyRequest,reply:FastifyReply)=>{await auth(r,reply);if(reply.sent)return;if(!hasPermission(r.session!,code))return reply.code(403).send({error:'forbidden',message:`缺少权限 ${code}`})}
const superAdmin=async(r:FastifyRequest,reply:FastifyReply)=>{await auth(r,reply);if(reply.sent)return;if(!r.session!.permissions.includes('*'))return reply.code(403).send({error:'super_admin_required',message:'仅超级管理员可以执行此操作'})}
async function audit(r:FastifyRequest,action:string,type:string,id?:string,details={}){await query(`INSERT INTO app.audit_logs(tenant_id,user_id,action,resource_type,resource_id,ip,details) VALUES($1,$2,$3,$4,$5,$6,$7)`,[r.session?.tenantId,r.session?.userId,action,type,id,r.ip,details])}
type Entitlements=Record<string,number|string[]>
async function currentEntitlements(tenantId:string){const row=(await query<{entitlements:Entitlements}>(`SELECT p.entitlements FROM app.subscriptions s JOIN app.plans p ON p.id=s.plan_id WHERE s.tenant_id=$1 AND s.status='active' AND s.period_end>now() ORDER BY s.created_at DESC LIMIT 1`,[tenantId])).rows[0];if(!row)throw Object.assign(new Error('租户没有有效订阅或订阅已到期'),{statusCode:402});return row.entitlements}
const quotaTables={providers:{table:'app.model_providers',where:'is_builtin=false',label:'模型供应商'},models:{table:'app.models',where:'true',label:'模型'},members:{table:'app.memberships',where:'true',label:'成员'}} as const
async function enforceResourceQuota(tenantId:string,key:keyof typeof quotaTables,additional=1){const quota=(await currentEntitlements(tenantId))[key],limit=typeof quota==='number'?quota:null;if(limit===null)return;const spec=quotaTables[key],used=(await query<{used:number}>(`SELECT count(*)::int used FROM ${spec.table} WHERE tenant_id=$1 AND ${spec.where}`,[tenantId])).rows[0].used;if(used+additional>limit)throw Object.assign(new Error(`当前套餐${spec.label}额度已用完（上限 ${limit}）`),{statusCode:429})}
async function enforceTenantMemberLimit(tenantId:string,additional=1){const row=(await query<{max_members:number|null;used:number}>(`SELECT t.max_members,(SELECT count(*)::int FROM app.memberships m WHERE m.tenant_id=t.id) used FROM app.tenants t WHERE t.id=$1`,[tenantId])).rows[0];if(row?.max_members&&row.used+additional>row.max_members)throw Object.assign(new Error(`租户成员上限为 ${row.max_members} 人`),{statusCode:429})}
async function enforceQuota(tenantId:string){const entitlements=await currentEntitlements(tenantId),quota=entitlements.api_calls;if(typeof quota!=='number')return;const row=(await query<{used:number}>(`SELECT coalesce(sum(u.api_calls),0)::int used FROM app.subscriptions s LEFT JOIN app.usage_events u ON u.tenant_id=s.tenant_id AND u.occurred_at BETWEEN s.period_start AND s.period_end WHERE s.tenant_id=$1 AND s.status='active' AND s.period_end>now()`,[tenantId])).rows[0];if(row.used>=quota)throw Object.assign(new Error('当前套餐 API 调用额度已用完'),{statusCode:429})}
async function resolveManagedTenant(session:Session,tenantId?:string){const target=tenantId??session.tenantId;if(target!==session.tenantId)assertPermission(session,'tenants:manage');if(!(await query(`SELECT 1 FROM app.tenants WHERE id=$1`,[target])).rowCount)throw Object.assign(new Error('租户不存在'),{statusCode:404});return target}
app.setErrorHandler((e,r,reply)=>{r.log.error(e);if(e instanceof z.ZodError)return reply.code(400).send({error:'validation_error',message:'输入数据不合法',details:e.issues});if((e as {code?:string}).code==='23505')return reply.code(409).send({error:'conflict',message:'名称或标识已存在'});const expected=e as Error&{statusCode?:number;publicCode?:string};if(expected.publicCode)return reply.code(expected.statusCode??400).send({error:expected.publicCode,message:expected.message});reply.code(expected.statusCode??500).send({error:'internal_error',message:config.production?'服务器内部错误':e instanceof Error?e.message:'未知错误'})})
