app.post('/api/auth/login',async r=>{const body=z.object({email:z.string().trim().email(),password:userPassword,captchaId:z.string().uuid(),captchaCode:z.string().trim().min(1).max(12)}).parse(r.body);if(!await verifyCaptcha(body.captchaId,body.captchaCode))throw Object.assign(new Error('验证码错误或已过期，请刷新后重试'),{statusCode:400,publicCode:'captcha_invalid'});const row=(await query<LoginRow>(`SELECT u.id,u.email,u.name,u.password_hash,m.tenant_id,r.name role,r.permissions,t.status,t.valid_from,t.valid_until FROM app.users u JOIN app.memberships m ON m.user_id=u.id JOIN app.roles r ON r.id=m.role_id JOIN app.tenants t ON t.id=m.tenant_id WHERE lower(u.email)=lower($1) AND u.status='active' LIMIT 1`,[body.email])).rows[0];if(!row||!await verifyPassword(body.password,row.password_hash))throw Object.assign(new Error('邮箱或密码错误'),{statusCode:401});if(tenantUnavailable(row))throw Object.assign(new Error('租户已停用或不在有效期内'),{statusCode:403});const token=createSessionToken(),session:Session={userId:row.id,tenantId:row.tenant_id,email:row.email,name:row.name,role:row.role,permissions:row.permissions};await redis.set(`session:${sha256(token)}`,JSON.stringify(session),'EX',86400);await query(`UPDATE app.users SET last_login_at=now() WHERE id=$1`,[row.id]);return ok({token,user:session})})
