const tenantSelect=`SELECT t.id,t.name,t.slug,t.description,t.locale,t.timezone,t.settings,t.status,t.valid_from,t.valid_until,t.max_members,t.created_at,t.updated_at,(CASE WHEN t.status<>'active' THEN t.status WHEN t.valid_from>now() THEN 'suspended' WHEN t.valid_until IS NOT NULL AND t.valid_until<=now() THEN 'expired' ELSE 'active' END) lifecycle_status,(SELECT count(*)::int FROM app.memberships m WHERE m.tenant_id=t.id) members,(SELECT count(*)::int FROM app.resource_categories c WHERE c.tenant_id=t.id AND c.resource_type='model') model_categories FROM app.tenants t`
const tenantCreateBody=z.object({name:z.string().min(2).max(100),slug:z.string().trim().regex(/^[a-z0-9][a-z0-9-]{1,78}[a-z0-9]$/).optional(),description:z.string().max(2000).default(''),locale:z.string().min(2).max(20).default('zh-CN'),timezone:z.string().min(2).max(50).default('Asia/Shanghai'),status:tenantStatus.default('active'),validFrom:tenantDate.optional(),validUntil:tenantDate.nullable().optional(),maxMembers:z.number().int().positive().nullable().optional(),settings:z.record(z.string(),z.boolean()).default({allow_api_keys:true,sync_models:true,failure_email:true}),owner:z.object({email:z.string().email(),name:z.string().min(2).max(100).optional(),password:userPassword.optional(),generatePassword:z.boolean().default(true)}).optional()}).superRefine((v,ctx)=>{const from=toTenantDate(v.validFrom)??new Date(),until=toTenantDate(v.validUntil);if(until&&until<=from)ctx.addIssue({code:'custom',message:'有效期结束时间必须晚于开始时间',path:['validUntil']})})
const tenantUpdateBody=z.object({name:z.string().min(2).max(100).optional(),slug:z.string().trim().regex(/^[a-z0-9][a-z0-9-]{1,78}[a-z0-9]$/).optional(),description:z.string().max(2000).optional(),locale:z.string().min(2).max(20).optional(),timezone:z.string().min(2).max(50).optional(),status:tenantStatus.optional(),validFrom:tenantDate.optional(),validUntil:tenantDate.nullable().optional(),maxMembers:z.number().int().positive().nullable().optional(),settings:z.record(z.string(),z.boolean()).optional()})
