app.post('/api/settings/brand-logo',{preHandler:permit('settings:manage')},async r=>{const part=await r.file();if(!part)throw Object.assign(new Error('请选择企业 Logo 文件'),{statusCode:400});const mimeExtensions:Record<string,string>={'image/png':'png','image/jpeg':'jpg','image/webp':'webp','image/svg+xml':'svg'},extension=mimeExtensions[part.mimetype];if(!extension)throw Object.assign(new Error('企业 Logo 仅支持 PNG、JPG、WebP 或 SVG 图片'),{statusCode:400});const content=await part.toBuffer();if(part.file.truncated||content.length>2*1024*1024)throw Object.assign(new Error('企业 Logo 文件不能超过 2MB'),{statusCode:400});const tenantId=r.session!.tenantId,path=join(config.uploadDir,tenantId,'brand',`${randomUUID()}.${extension}`);await mkdir(join(config.uploadDir,tenantId,'brand'),{recursive:true});await writeFile(path,content);await query(`UPDATE app.tenants SET brand_logo_path=$1,brand_logo_mime_type=$2,updated_at=now() WHERE id=$3`,[path,part.mimetype,tenantId]);await audit(r,'tenant.brand.logo.update','tenant',tenantId,{mimeType:part.mimetype,sizeBytes:content.length});return ok({brand_logo_url:`/api/tenant-brand/${tenantId}/logo?updatedAt=${Date.now()}`})})
