app.post('/api/channel-notification-webhooks/:type/:accountId',async r=>{const params=z.object({type:channelType,accountId:z.string().uuid()}).parse(r.params),account=(await query<{callback_url:string|null}>(`SELECT callback_url FROM app.channel_notification_accounts WHERE id=$1 AND channel_type=$2`,[params.accountId,params.type])).rows[0];if(!account)throw Object.assign(new Error('渠道配置不存在'),{statusCode:404});if(!account.callback_url)return ok({accepted:true,forwarded:false});const response=await fetch(account.callback_url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(r.body??{})});if(!response.ok)throw Object.assign(new Error(`业务回调返回 ${response.status}`),{statusCode:502});return ok({accepted:true,forwarded:true})})
